 IEnumerable<WorkflowSourceOption> GroupRunSources(WorkflowRunParameter proxy){var body=GroupBody();var target=body.Nodes.Single(n=>n.Id==proxy.NodeId);var d=groupRegistry!.GetDescriptor(target);var input=proxy.IsInput?d.Inputs.Single(p=>p.Name==proxy.Parameter):null;var kind=input?.Kind??WorkflowSubscriptions.ParameterType(d.Parameters.Single(p=>p.Name==proxy.Parameter).Kind);var cardinality=input?.Cardinality??ValueCardinality.Scalar;bool Accept(DataKind source)=>proxy.IsInput?DataKinds.CanFlow(source,input!):source==kind;foreach(var option in groupSources!(kind).Where(s=>s.NodeId!=target.Id&&s.Cardinality==cardinality&&Accept(s.Kind)))yield return option with{Reference=new(WorkflowSourceKind.NodeOutput,option.NodeId,option.Port)};foreach(var i in body.Configuration.Inputs.Where(i=>i.Cardinality==cardinality&&Accept(i.Kind)))yield return new("input:"+i.Id,i.Name,i.Kind,"Group输入."+i.Name){Reference=new(WorkflowSourceKind.WorkflowInput,i.Id),Cardinality=i.Cardinality};if(cardinality==ValueCardinality.Scalar){foreach(var v in body.Configuration.Variables.Where(v=>Accept(WorkflowSubscriptions.VariableKind(v.Type))))yield return new("var:"+v.Id,v.Name,WorkflowSubscriptions.VariableKind(v.Type),"局部变量."+v.Name){Reference=new(WorkflowSourceKind.LocalVariable,v.Id)};if(kind==DataKind.Integer)yield return new("loop","LoopIndex",kind,"Group.LoopIndex"){Reference=new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")};}}
